import * as fs from 'fs';

export interface FlowStepRow {
  instance?: string | number;
  [key: string]: any;
}

function getStepDataPath(): string | undefined {
  return process.env.STEP_DATA;
}

/**
 * Reads the STEP_DATA file generated by the ordered runner and returns the
 * configured instance IDs. Falls back to the INSTANCE/INSTANCES environment
 * variables when STEP_DATA is not available. Returns undefined only when no
 * selection source exists, allowing callers to fall back to all available data.
 */
export function getSelectedInstances(stepDataPath: string | undefined = getStepDataPath()): string[] | undefined {
  if (stepDataPath && fs.existsSync(stepDataPath)) {
    try {
      const content = JSON.parse(fs.readFileSync(stepDataPath, 'utf8'));
      const instances = new Set<string>();
      for (const value of Object.values(content)) {
        if (Array.isArray(value)) {
          for (const row of value as FlowStepRow[]) {
            if (row.instance != null && String(row.instance).trim() !== '') {
              instances.add(String(row.instance).trim());
            }
          }
        }
      }
      if (instances.size > 0) {
        return Array.from(instances);
      }
    } catch (e) {
      console.log(`[getSelectedInstances] Could not read STEP_DATA: ${e}`);
    }
  }

  if (process.env.INSTANCES) {
    return process.env.INSTANCES.split(',').map((s) => s.trim()).filter(Boolean);
  }

  if (process.env.INSTANCE) {
    return [String(process.env.INSTANCE).trim()];
  }

  return undefined;
}
